def verified(sha256: str) -> Optional[str]:
    """Which official Unity player file has this SHA-256 (None: not in the table)."""
    entry = FILES.get((sha256 or "").lower())
    if entry is None:
        return None
    engine, version = ARCHIVES[entry[1]][:2]
    return "%s - %s %s (Windows player)" % (entry[0].rsplit("/", 1)[-1], engine, version)


def verified_program(frame_key: Optional[str], resources: Optional[str]) -> Optional[str]:
    """Which official Unity player program this is apart from its icons (None: not in the
    table) - ``frame_key`` of ``gamescan.pe.resource_frame_key`` (signature's place left out),
    ``resources`` of ``gamescan.pe.resources_but_icons``; both must be the official program's."""
    entry = PROGRAMS.get(frame_key or "")
    if entry is None or resources is None or entry[3] != resources:
        return None
    engine, version = ARCHIVES[entry[1]][:2]
    return "%s - %s %s (Windows player)" % (entry[0].rsplit("/", 1)[-1], engine, version)
